#include <unordered_map>
#include <algorithm>
using namespace std;

class AuctionSystem {
    unordered_map<int, unordered_map<int, int>> item_bids;
public:
    AuctionSystem() {}

    void placeBid(int item_id, int user_id, int amount) {
        item_bids[item_id][user_id] = amount;
    }

    int getHighestBid(int item_id) {
        if (!item_bids.count(item_id) || item_bids[item_id].empty()) return 0;
        int mx = 0;
        for (const auto& [u, amt] : item_bids[item_id]) {
            mx = max(mx, amt);
        }
        return mx;
    }

    void withdrawBid(int item_id, int user_id) {
        if (item_bids.count(item_id)) {
            item_bids[item_id].erase(user_id);
        }
    }
};

import java.util.*;

class AuctionSystem {
    private Map<Integer, Map<Integer, Integer>> itemBids;

    public AuctionSystem() {
        itemBids = new HashMap<>();
    }

    public void placeBid(int itemId, int userId, int amount) {
        itemBids.computeIfAbsent(itemId, k -> new HashMap<>()).put(userId, amount);
    }

    public int getHighestBid(int itemId) {
        Map<Integer, Integer> bids = itemBids.get(itemId);
        if (bids == null || bids.isEmpty()) return 0;
        int mx = 0;
        for (int amt : bids.values()) mx = Math.max(mx, amt);
        return mx;
    }

    public void withdrawBid(int itemId, int userId) {
        Map<Integer, Integer> bids = itemBids.get(itemId);
        if (bids != null) bids.remove(userId);
    }
}

var AuctionSystem = function() {
    this.itemBids = new Map();
};

AuctionSystem.prototype.placeBid = function(item_id, user_id, amount) {
    if (!this.itemBids.has(item_id)) this.itemBids.set(item_id, new Map());
    this.itemBids.get(item_id).set(user_id, amount);
};

AuctionSystem.prototype.getHighestBid = function(item_id) {
    const bids = this.itemBids.get(item_id);
    if (!bids || bids.size === 0) return 0;
    let mx = 0;
    for (const amt of bids.values()) mx = Math.max(mx, amt);
    return mx;
};

AuctionSystem.prototype.withdrawBid = function(item_id, user_id) {
    const bids = this.itemBids.get(item_id);
    if (bids) bids.delete(user_id);
};
